mapper.select:
SELECT MAX(version_no)
FROM t_payment_channel_version
WHERE channel_code = #{channelCode}

SELECT COALESCE(MAX(version_no), 0)
FROM t_payment_route_rule_version
WHERE rule_code = #{ruleCode}

SELECT MAX(version_no)
FROM t_payment_protocol_version
WHERE protocol_code = #{protocolCode}

SELECT MAX(version_no)
FROM t_payment_control_policy_version
WHERE source_app_id = #{sourceAppId}

mapper.update:
UPDATE t_payment_channel_return_code_map
SET status = #{status},
    status_type = #{statusType},
    updated_at = NOW()
WHERE channel_code = #{channelCode}
  AND channel_return_code = #{channelReturnCode}
